import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define THREADS 512
#define WARPS_PER_BLOCK (THREADS / 32)
#define ROWS_PER_BLOCK WARPS_PER_BLOCK
#define TILE_K 4096
__device__ __forceinline__ float warpReduceSum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffffu, val, offset);
    return val;
}
// C = A * B, with A of shape (M, K) and B of shape (K, 1).
// N is tiny and K is huge. Tile rows across the CTA: one warp owns one
// output row, while the whole block stages each B tile in shared memory once
// and reuses it across ROWS_PER_BLOCK rows. This removes split-K atomics and
// cuts repeated global reads of B by ROWS_PER_BLOCK.
__global__ void matvec_kernel(const float* __restrict__ A,
                              const float* __restrict__ B,
                              float* __restrict__ C,
                              long M,
                              long K,
                              int vec4) {
    __shared__ __align__(16) float smemB[TILE_K];
    const long row0 = (long)blockIdx.x * ROWS_PER_BLOCK;
    const int lane = threadIdx.x & 31;
    const int wid  = threadIdx.x >> 5;
    const long row = row0 + wid;
    const float* aRow = A + row * K;
    float acc = 0.0f;
        const long num_tiles = (K + TILE_K - 1) / TILE_K;
        const long tile0 = (num_tiles * blockIdx.y) / gridDim.y;
        const long tile1 = (num_tiles * (blockIdx.y + 1)) / gridDim.y;
        if (tile0 >= tile1) return;
        const long k_begin = tile0 * TILE_K;
        const long k_end = ((tile1 * TILE_K) < K) ? (tile1 * TILE_K) : K;
        for (long k0 = k_begin; k0 < k_end; k0 += TILE_K) {
            const int len = (int)(((k0 + TILE_K) < k_end) ? TILE_K : (k_end - k0));
        if (vec4) {
            const int len4 = len >> 2;
            const float4* b4 = reinterpret_cast<const float4*>(B + k0);
            float4* s4 = reinterpret_cast<float4*>(smemB);
            for (int i = threadIdx.x; i < len4; i += THREADS) {
                s4[i] = b4[i];
            }
        } else {
            for (int i = threadIdx.x; i < len; i += THREADS) {
                smemB[i] = B[k0 + i];
            }
        }
        __syncthreads();
        if (row < M) {
            float s = 0.0f;
            if (vec4) {
                const int len4 = len >> 2;
                const float4* a4 = reinterpret_cast<const float4*>(aRow + k0);
                const float4* sb4 = reinterpret_cast<const float4*>(smemB);
                for (int i = lane; i < len4; i += 32) {
                    const float4 a = a4[i];
                    const float4 b = sb4[i];
                    s += a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
                }
            } else {
                for (int i = lane; i < len; i += 32) {
                    s += aRow[k0 + i] * smemB[i];
                }
            }
            acc += warpReduceSum(s);
        }
        __syncthreads();
    }
    if (row < M && lane == 0) {
        atomicAdd(C + row, acc);
    }
}
torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B) {
    const long M = A.size(0);
    const long K = A.size(1);
    auto C = torch::zeros({M, 1}, A.options());
    const int vec4 = ((K & 3) == 0) ? 1 : 0;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    const long grid_x = (M + ROWS_PER_BLOCK - 1) / ROWS_PER_BLOCK;
    long split_k = 8;
    const long num_tiles = (K + TILE_K - 1) / TILE_K;
    if (num_tiles < split_k) split_k = (num_tiles > 0) ? num_tiles : 1;
    dim3 grid((unsigned int)grid_x, (unsigned int)split_k);
    matvec_kernel<<<grid, THREADS, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K,
        vec4);
    return C;
}
"""

cpp_source = "torch::Tensor matvec_cuda(torch::Tensor A, torch::Tensor B);"

matvec_module = load_inline(
    name="matvec_ext",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["matvec_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Matrix-vector multiplication (C = A * B) implemented with a custom CUDA kernel.
    A: (M, K), B: (K, 1) -> C: (M, 1)
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        out_device = A.device

        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()

        A = A.contiguous().float()
        B = B.contiguous().float()

        C = matvec_module.matvec_cuda(A, B)
        return C.to(out_device)

